import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"34、【大壯】 乾下震上","description":"周易集註 - 34、【大壯】 乾下震上","frontmatter":{"title":"34、【大壯】 乾下震上","description":"周易集註 - 34、【大壯】 乾下震上"},"headers":[],"relativePath":"classics/jizhu/038.md","filePath":"classics/jizhu/038.md"}'),t={name:"classics/jizhu/038.md"};function h(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_34、【大壯】-乾下震上" tabindex="-1">34、【大壯】 乾下震上 <a class="header-anchor" href="#_34、【大壯】-乾下震上" aria-label="Permalink to “34、【大壯】 乾下震上”">​</a></h1><p>大壯者，大者壯也。大謂陽也，四陽盛長，故為大壯，二月之卦也。為卦震上幹下，乾剛而震動，大壯之義也。又雷之威震於天上，聲勢壯大，亦大壯之義也。《序卦》：“遁者退也，物不可以終遁，故受之以大壯。”遁者陽衰而遁也，壯者陽盛而壯。衰則必盛，消長循環之理，所以次遁。</p><p>陽壯則佔者吉亨，不必言矣。然君子所謂壯者，非徒以其勢之盛，乃其理之正也，故利於正。陰之進不正，則小人得以陵君子，故遁言小者利於貞。陽之進不正，則君子不能勝小人，故大壯言大者利於貞。大壯綜遁，二卦本是一卦，故卦下之辭如此。</p><p>《彖》曰：大壯，大者壯也，剛以動故壯。大壯利貞，大者正也，正大而天地之情可見矣!</p><p>以卦體卦德釋卦名，又釋利貞之義而極言之。陽長過中，大者壯也。蓋正月泰，陽雖長而未盛，三月夬，陽已盛而將衰，皆不可以言壯，惟四陽則壯矣。且乾剛震動，剛則能勝其人慾之私，動則能奮其必為之志，何事不可行哉，此其所以壯也。卦體則勢壯，卦德則理壯，所以名壯。大者正也，言大者自無不正也。凡陽明則正，陰濁則邪，自然之理，故利於貞，若不貞則非大矣。正大者，正則無不大也。天地之情者，覆載生成所發之情也，一通一復，皆一誠之貫徹，豈不正?既正豈不大?故曰正大。蓋大者壯，以氣言，乃壯之本體也。大者正，以理言，所以運壯之道也。正大而天地之情可見，又推極上天下地，莫非此正大之理，非特人為然也。一陽來複，見天地之心，四陽見其情。仁者天地之心，情則其所發也。</p><h3 id="《象》曰-雷在天上-大壯-君子以非禮弗履。" tabindex="-1">《象》曰：雷在天上，大壯，君子以非禮弗履。 <a class="header-anchor" href="#《象》曰-雷在天上-大壯-君子以非禮弗履。" aria-label="Permalink to “《象》曰：雷在天上，大壯，君子以非禮弗履。”">​</a></h3><p>非禮者，人慾之私也。履者踐履也，非禮弗履，則有以克勝其人慾之私矣，此惟剛健以動者可能。矯哉其強，何壯如之，雷在天上，大壯者，以聲勢而見其壯也。君子非禮弗履，大壯者以克勝其私，而見其壯也。</p><p>初九，壯於趾，徵兇，有孚。</p><p>震為足，又初在下，趾之象也。徵兇者，往則必裁抑擯斥也。孚者，自信其陽剛之正德也。初以陽居陽，幹之剛未盛也，故有孚。至三則乾剛極矣，故貞厲。</p><p>初九，陽剛處下，當壯之時，壯於進者也，故有壯趾之象。以是而往，兇之道也。然陽剛居正，本有其德，故教佔者，惟自信其德，以甘窮困，不可有所往，往則兇矣。</p><h3 id="《象》曰-壯於趾-其孚窮也。" tabindex="-1">《象》曰：壯於趾，其孚窮也。 <a class="header-anchor" href="#《象》曰-壯於趾-其孚窮也。" aria-label="Permalink to “《象》曰：壯於趾，其孚窮也。”">​</a></h3><p>既無應援，又卑下無位，故曰窮。當壯進之時，有其德而不能進，進則必兇，乃處窮之時矣，故惟自信其德，以自守可也。是其孚者，不得已也，因窮也，故曰其孚窮。賢人君子，不偶於時，棲止山林者，多是如此。</p><p>九二，貞吉。</p><p>中則無太過，不恃其強而猛於必進，所以此爻貞吉。</p><p>九二以陽剛當大壯之時，居中而不過於壯，蓋正而吉者也，故其佔如此。</p><h3 id="《象》曰-九二貞吉-以中也。" tabindex="-1">《象》曰：九二貞吉，以中也。 <a class="header-anchor" href="#《象》曰-九二貞吉-以中也。" aria-label="Permalink to “《象》曰：九二貞吉，以中也。”">​</a></h3><p>以中者，居中位也，與解卦得中道，未濟中以行正同。中立而不倚強哉矯，九二有焉。</p><p>九三，小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。羸力為切</p><p>罔者無也，言不用也。君子以義理為勇，以非禮弗履為大壯，故不用壯也。羝羊，壯羊也。羸者瘦也，病也。羝羊恃其強壯，乃觸其藩，其角出於藩之外，易去而難反，不能用其力，是角之壯者，反為藩所困制而弱病矣，故曰羸其角也。本卦大象兌，中爻為兌，皆羊之象，故諸爻皆以羊言之。震為竹為葦，藩之象也。觸藩者，用壯之象也。陽居陽位，故曰貞。羸角者，又貞厲之象也。</p><p>九三過剛不中，又當幹體之終，交震動之際，乃純用血氣之強，過於壯者也。然用壯為小人之事，君子以義理為主，豈其所用哉，故聖人戒佔者曰，惟小人則用壯，君子則不用也。茍用其壯，雖正亦厲，亦如羊之觸藩羸角也，壯其可恃哉。戒之之嚴，故佔中之象又如此。</p><h3 id="《象》曰-小人用壯-君子罔也。" tabindex="-1">《象》曰：小人用壯，君子罔也。 <a class="header-anchor" href="#《象》曰-小人用壯-君子罔也。" aria-label="Permalink to “《象》曰：小人用壯，君子罔也。”">​</a></h3><p>言用壯者，小人之事，君子則無此也。</p><p>九四，貞吉，悔亡。藩決不羸，壯於大輿之輹。</p><p>貞吉悔亡者，惟正則吉，而悔亡也。決，破也，藩決不羸，承上文而言也。三前有四之阻隔，猶有藩焉。四前二陰，則藩決而可前進矣。震為大塗，兌為附決，藩決之象也。輹與輻同，車輪之中幹也。車之敗，常在折輹，輹壯則車強。四變坤，大輿之象也。壯於大輿之輹，言尚往而可進也。此二句，又貞吉悔亡之象也。</p><p>九四當大壯之時，以陽居陰，不極其剛，前無困阻，而可以尚往矣，故其佔中之象如此。</p><h3 id="《象》曰-藩決不羸-尚往也。" tabindex="-1">《象》曰：藩決不羸，尚往也。 <a class="header-anchor" href="#《象》曰-藩決不羸-尚往也。" aria-label="Permalink to “《象》曰：藩決不羸，尚往也。”">​</a></h3><p>尚往者，前無困阻，而可以上進也。</p><p>六五，喪羊於易，無悔。易音亦</p><p>易即埸，田畔也。震為大塗，埸之象也。</p><p>本卦四陽在下，故名大壯，至六五無陽，則喪失其所謂大壯矣。故有喪羊於易之象，既失其壯，則不能前進，僅得無悔而已，故其象佔如此。</p><h3 id="《象》曰-喪羊於易-位不當也。" tabindex="-1">《象》曰：喪羊於易，位不當也。 <a class="header-anchor" href="#《象》曰-喪羊於易-位不當也。" aria-label="Permalink to “《象》曰：喪羊於易，位不當也。”">​</a></h3><p>位不當者，以柔居五位也。</p><p>上六，羝羊觸藩，不能退，不能遂，無攸利，艱則吉。</p><p>震錯巽，為進退，退遂之象也。艱者，處之艱難而不忽慢也。吉者，無攸利者，終得攸利也。六五已喪羊矣，而上六又羝羊觸藩者，蓋六五以一爻言也。上六則合一卦而言也，三則剛之極，上則動之極，所以爻象皆同。</p><p>上六壯終動極，所以觸藩而不能退。然其質本柔，又不能遂其進也，故有觸藩不能退遂之象。佔者之無攸利可知矣。然猶幸其不剛，而不妄進也。若佔者能艱以處之，則得以遂其進而吉矣。</p><h3 id="《象》曰-不能退-不能遂-不詳也-艱則吉-咎不長也。" tabindex="-1">《象》曰：不能退，不能遂，不詳也;艱則吉，咎不長也。 <a class="header-anchor" href="#《象》曰-不能退-不能遂-不詳也-艱則吉-咎不長也。" aria-label="Permalink to “《象》曰：不能退，不能遂，不詳也;艱則吉，咎不長也。”">​</a></h3><p>詳者，慎密也。不詳者，當壯終動極之時，不能度勢而行，審幾而進也。既詳則能艱矣。咎者不能退、不能遂之咎也，惟艱則能詳而咎不長矣。心思之艱難，所以能詳，識見之詳明，所以方艱。</p>',37)])])}const f=e(t,[["render",h]]);export{_ as __pageData,f as default};
